  if(c.w<0.03||o.w<0.03)return vec4(2.0,2.0,2.0,1.0);
  vec2 d=(o.xy/o.w-c.xy/c.w)*cc_screenSize.xy;
  float len=length(d);
  if(len<1.0)return vec4(2.0,2.0,2.0,1.0);
  c.xy+=vec2(-d.y,d.x)/len*a_color.w*lightInfo.z*clamp(1.35-dist*0.085,0.5,1.0)*cc_screenSize.y*0.002778*cc_screenSize.zw*c.w;
  return c;
}
